				},
				{
					"id": "o3",
					"text": "Four"
				},
				{
					"id": "o4",
					"text": "It varies"
				}
			],
			"question": "How many arguments does an Express error-handling middleware take?"
		},
		{
			"id": "q4",
			"marks": 5,
			"options": [
				{
					"id": "o1",
					"text": "Readable"
				},
				{
					"id": "o2",
					"text": "Writable"
				},
				{
					"id": "o3",
					"text": "Duplex"
				},
				{
					"id": "o4",
					"text": "Transform"
				}
			],
			"question": "Which stream type would you use to transform data as it passes through?"
		}
	],
	"answer": [
		{
			"answer": "o2",
			"questionId": "q1"
		},
		{
			"answer": "o2",
